from azure.eventhub import EventHubConsumerClient

def consume_event():
    client = EventHubConsumerClient.from_connection_string(conn_str="Endpoint=sb://<namespace>.servicebus.windows.net/;SharedAccessKeyName=<keyName>;SharedAccessKey=<key>;EntityPath=<eventHubName>")
    with client:
        received_events = client.receive(on_event=on_event, starting_position="-1")
        for event in received_events:
            print("Received event: ", event.body_as_str())

def on_event(event):
    print("Received event: ", event.body_as_str())

from azure.eventhub import EventHubProducerClient, EventHubConsumerClient

def get_producer_client():
    return EventHubProducerClient.from_connection_string(conn_str="Endpoint=sb://<namespace>.servicebus.windows.net/;SharedAccessKeyName=<keyName>;SharedAccessKey=<key>;EntityPath=<eventHubName>")

def get_consumer_client():
    return EventHubConsumerClient.from_connection_string(conn_str="Endpoint=sb://<namespace>.servicebus.windows.net/;SharedAccessKeyName=<keyName>;SharedAccessKey=<key>;EntityPath=<eventHubName>")

class Event:
    def __init__(self, body):
        self.body = body

    def to_json(self):
        return {"body": self.body}

    @staticmethod
    def from_json(json_obj):
        return Event(json_obj["body"])

def summarize_messages(messages):
    summary = {"total_messages": len(messages), "message_bodies": []}
    for message in messages:
        summary["message_bodies"].append(message.body)
    return summary

import re

def check_safety(message):
    unsafe_patterns = [r"badword1", r"badword2"]
    for pattern in unsafe_patterns:
        if re.search(pattern, message):
            return False
    return True
